"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Meteorita xoş gəldin! Sən Konsorsiumun döyüş robotusan. Siçanla ətrafa bax, WASD ilə get.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Ranets: Shift-ə toxun — tullanma, Shift-i bas saxla — uçuş. Enerji yerdə bərpa olunur.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Atəş — chap tugma. Nişan — oʻng tugma: daha dəqiq və yaxınlaşdırma ilə. Bir neçə atəş et.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Doldurma — R. Güllələr orta məsafədə, 20–50 metrdə ən güclü vurur.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Raket — Q. Tank və binalara qarşı. Raket at.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Yuxarıda AI-strategin tapşırığı var. Yaşıl oxlarla qaç: marşrutda sprintin var. Nöqtəni ələ keçir — mayakın yanında dur.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Otryadın arxanı qoruyur: solda onların portretləri və sağlamlığı var. Geri qalsalar, gözləməyi xahiş edəcəklər.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — döyüşdən çıxmadan döyüşçünü tez dəyiş: döyüşə ən yaxın otryada və ya tanka tullan. Yoxla.",
