"New in v6.2":"v6.2-də yeni",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Yeni ruda görünüşü: ruda damarları qara bazalt üzərində qığılcımlı və yaşıl dumanlı parlayan zümrüd kəsik kristallardır; Ekstraktor — altıbucaqlı postament, petək günbəz və yaşıl işıqlı mayaklı qəfəs qüllədir (zolaq və bayraqcıq — komanda rəngində)",
"New in v6.1":"v6.1-də yeni",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Battlefield-dəki kimi seçdiyin sinif (U, həlak olandan sonra rəqəmlər): mümkün olanda onun içinə girirsən",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Texnika birinci şəxsdən (V — kənardan/kabinədən); yüngül avto-hədəfləmə — Ayarlarda",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Nüvədən çıxmaq asandır: Boşluq — şaxtaya, B — kapsul səthə; qabiliyyət effektləri həlak olanda sıfırlanır",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Sonsuz inkişaf: generallar və Marşal ★, karyera səviyyələri, silah ustalığı və əlavələr, medallar, gündəlik tapşırıqlar — Karyera ekranı",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Strategiya: təkər ilə hamar zum, yunitlərin üstündə ikonlar və yazılar (Alt — hamısı), solda «Qoşunlar / Binalar» paneli",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"sağ düymə — hücum-hərəkət, 2× sağ düymə — hərəkətdə atəşlə yürüş; nadir əmrlər — «Daha çox əmr ▾»; düymələr təkrarlanmır",
"New in v6":"v6-da yeniliklər",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Atıcı tipli silahlar: ani güllələr, dəqiqədə 720 atəşli avtomat, pulemyot, geri təpmə, sağ düymə ilə nişan, məmbələr və R ilə yenidən doldurma, vurma işarələri",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Daha ağır cazibə, çevik reaktiv çanta, Z ilə və ya havada 2× çanta ilə sıçrayış; başqa döyüşçüyə keçəndə silah artıq onunla uçmur",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Muhandislər: muhandisi seç, bina seç, plan yerləşdir; Ekstraktorlar ruda damarlarındadır; gəlirin haradan gəldiyini və necə artacağını görmək üçün «RUDA»ya klik et",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Boz düymələr səbəbi izah edir və həll təklif edir; iri düymələr, «İcradadır» zolağı, «▶ Boshqarish», Tab — vahid rejim düyməsi",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Sıçrayışsız və çevrilməsiz strategiya kamerası, kursora zum, minixəritəni sürüşdürmək olur",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Yeni texnika: \"Chiyaboʻri\" reyderi, \"Grad\" (özünəyönəlmə raketləri), \"Bolgʻa\" minaatanı; Gala \"Ari\", \"Uya\", \"Manjaniq\" alır",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Strateg əmrləri dəyişmir və səslə spam etmir; döyüşlər sənin yanında olur; B — köçürmə, Shift+B — döyüşün içinə; kompas, H — hansı hədəf",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Sərbəst oyun (K) və tək hərəkət (J), F2 — presetlər; Esc — pauza və geri; yaddaşlar: slotlar, faylın ixracı və idxalı",
"New in v5.3":"v5.3-də yeniliklər",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Uçuş: meteoritdən uzaqda cazibə güclüdür, havada C — əyləc, itələmə daha kəskin döndərir; artıq portalda «asılıb qalmırsan»",
"New in v5":"v5-də yeniliklər",
"Endless war by default and battle scale: normal, large, epic":"Defolt olaraq sonsuz döyüş və döyüş miqyası: adi, iri, epik",
"Save and load the battle (autosave every 3 minutes)":"Döyüşün saxlanması və yüklənməsi (və hər 3 dəqiqədən bir avto-yadda saxlama)",
"Squadmates with callsigns: portraits, health and live chatter":"Çağırış adlı otryad: portretlər, sağlamlıq və canlı danışıqlar",
"Fog of war in strategy, friends and foes outlined differently":"Strategiyada müharibə dumanı, dostlar və düşmənlər fərqli işıqlandırılır",
"Camera fly-over when switching, portal aurora instead of rings":"Keçid zamanı kameranın uçuşu, halqaların əvəzinə portal şəfəqi",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Əlavə tapşırıqlar, səmadan qısa yol, təchizatlı birinci ekspedisiya yaşayış modulları, kristallar, kraterlərdə buz, toz fırtınaları",
