"⚔ Polygon: an endless battle at the map centre with reinforcements. X — possess a soldier there":"⚔ Poliqon: xəritənin mərkəzində fasiləsiz döyüş, əlavə qüvvələrlə. X — poliqondakı döyüşçünü ələ keçir",
