"Phone: new shooter controls — stick, Fire and Jet on the left, look by swipe or a second stick on the right; AUTO locks on with a red frame like Syphon Filter: your trooper keeps the target and fires, the stick circles around it, a swipe flicks to the next target":"Telefon: atıcı üçün yeni idarəetmə — solda stik, «Atəş» və «Ranets», sağda sürüşdürmə və ya stiklə baxış; «AVTO» Syphon Filter-dəki kimi qırmızı çərçivə ilə hədəfi tutur: jangchin hədəfi özü saxlayıb atır, stiklə ətrafında dolanırsan, sürüşdürməklə növbəti hədəfə keçirsən",
"Gestures: double tap on the right — reflex; tap the red frame — rocket, swipe \"Grenade\" up — a grenade right at the target (or variant B — pinch); first-run gesture hints, icons instead of words, skills and \"hide HUD\" at the top":"Jestlər: sağda 2× toxun — refleks; qırmızı çərçivəyə toxun — raket, «Qumbara»nı yuxarı sürüşdür — qumbara düz hədəfə (və ya B variantı — sıxma); ilk açılışda jest göstərişləri, sözlər əvəzinə işarələr, yuxarıda bacarıqlar və «HUD-u gizlət»",
"Strategy on the phone: tap to select and order, hold for a radial menu (attack, hold, patrol, build, rally), hold and drag for a box, double tap for all of a type on screen; infantry / vehicles / drones / builders buttons, squad cards 1-2-3, follow camera, haptic ticks":"Telefonda strategiya: toxun — seç və əmr ver, basıb saxla — dairəvi menyu (hücum, dayan, patrul, tik, toplan), basıb saxla və dartı — çərçivə, 2× toxun — ekrandakı eyni tipdən hamısı; «piyada / texnika / dronlar / muhandislər» düymələri, 1-2-3 otryad kartları, «izlə», vibrasiya cavabı",
"Phone menus without sliders or scrolling: every section is its own screen with big buttons, languages as flags, \"− value +\", \"Back / ✕ / Apply\"":"Telefonda sürgüsüz və sürüşdürmə olmadan menyular: hər bölmə böyük düymələrlə ayrıca ekrandır, dillər bayraqlarla, «− dəyər +», «Geri / ✕ / Tətbiq et»",
"Developer mode: \"Polygon\" in the Arsenal — an endless battle of every squad type and vehicle at the map centre with reinforcements for both sides; X takes you straight into a soldier there (PC and phone)":"Developer rejimi: Arsenalda «Poliqon» — xəritənin mərkəzində bütün tip otryadların və bütün texnikanın fasiləsiz döyüşü, hər iki tərəfə əlavə qüvvələr; X — dərhal poliqondakı jangchiyə keçirir (PC və telefon)",
"PC":"PC",
"Move the mouse to turn your view.":"Siçanı hərəkət etdir — baxışın dönür.",
"{0} {1} {2} {3} — walk. Reach the green marker.":"{0} {1} {2} {3} — hərəkət et. Yaşıl nişana çat.",
"Hold {0} — the jetpack lifts you up.":"{0} basıb saxla — ranets səni havaya qaldıracaq.",
"Take off ({0}) and press {1} in the air — brake.":"Havaya qalx ({0}) və havada {1} bas — əyləc.",
"Aim at a dummy and press LMB.":"Manekenə nişan al və chap tugma bas.",
"Hold RMB — aim with zoom.":"Oʻng tugmani basıb saxla — yaxınlaşdırmalı nişan.",
"Press {0}.":"{0} bas.",
"Aim at a dummy and press {0}.":"Manekenə nişan al və {0} bas.",
"Press {0} to throw (hold longer — farther).":"{0} bas — atış (nə qədər çox saxlasan, bir o qədər uzağa).",
"Get behind the wall until the sniper marker turns grey.":"Snayper nişanı boz olana qədər divarın arxasına keç.",
"Press {0} — \"squad with me ⇄ going solo\".":"{0} bas — «otryad mənimlə ⇄ tək hərəkət edirəm».",
"Press {0} or \"◩ Strategy\" at the top left.":"{0} bas və ya solda yuxarıdakı «◩ Strategiya»nı seç.",
"Press {0} or the green \"▶ Possess\" below.":"{0} bas və ya aşağıdakı yaşıl «▶ İdarə et» düyməsini seç.",
"W A S D or arrows move the camera (or push the mouse to the screen edge).":"W A S D və ya oxlar — kameranı sürüşdür (və ya siçanı ekranın kənarına apar).",
"Scroll the mouse wheel.":"Siçan çarxını fırlat.",
"LMB on the squad with the green marker.":"Yaşıl nişanlı otryada chap tugma ilə toxun.",
"RMB on the yellow marker on the ground (double RMB — run).":"Yerdəki sarı nişana oʻng tugma ilə toxun (2× oʻng tugma — qaçaraq).",
"Ctrl + LMB on a squad — all of that type on screen get selected.":"Ctrl + chap tugma otryadın üzərində — ekrandakı eyni tipdən hamısı seçiləcək.",
"Hold LMB on empty ground and drag a box over the squads.":"Boş yerdə chap tugmani basıb saxla və çərçivəni otryadların üzərindən dartı.",
"LMB on the minimap at the bottom left — the camera jumps there.":"Solda aşağıdakı mini xəritəyə chap tugma — kamera ora keçəcək.",
"LMB on the marked builder (or \".\" — nearest builder).":"Nişanlı muhandisə chap tugma (və ya «.» — ən yaxın muhandis).",
"\"Barracks\" on the right ({0}), then LMB on the ground at the marker.":"Sağdakı «Kazarma» ({0}), sonra nişanın yanında yerə chap tugma.",
"No input needed — watch the building rise.":"Heç nə basmaq lazım deyil — binanın necə ucaldığına bax.",
"LMB on the Barracks → \"Assault squad\" on the right.":"Kazarmaya chap tugma → sağdan «Hücum otryadı».",
"Select a builder and RMB on the green crystals.":"Muhandisi seç və yaşıl kristallara oʻng tugma bas.",
"Drag a finger on the right half of the screen.":"Ekranın sağ yarısında barmağını sürüşdür.",
"Touch the left side and slide — that is the stick. Reach the green marker.":"Solda ekrana toxun və barmağını apar — bu, stikdir. Yaşıl nişana çat.",
"Hold the \"Jet\" button.":"«Çanta» düyməsini basıb saxla.",
"Aim at a dummy with your right finger and hold \"Fire\".":"Sağ barmağınla manekenə nişan al və «Atəş»i basıb saxla.",
"Tap \"Reload\".":"«Doldur»a toxun.",
"Tap \"AUTO\" — a red frame locks the dummy and your trooper fires.":"«AVTO»ya toxun — qırmızı çərçivə manekeni tutacaq, piyada özü atəş açacaq.",
"Tap the red frame on the target — a rocket flies. (No frame? Turn on \"AUTO\".)":"Hədəfdəki qırmızı çərçivəyə toxun — raket uçacaq. (Çərçivə yoxdur? «AVTO»nu aç.)",
"Rocket fired from the skills row. Try tapping the red frame itself.":"Raket bacarıqlar sırasından atıldı. Birbaşa qırmızı çərçivəyə toxunmağa çalış.",
"Swipe up on \"Grenade\" — it flies right at the target.":"«Qumbara»nı yuxarı sürüşdür — qumbara düz hədəfə uçacaq.",
"That was a normal throw. Now swipe up on the button — at the target.":"Bu adi atış idi. İndi düymədə yuxarı sürüşdür — hədəfə.",
"Double tap quickly on the right half of the screen.":"Ekranın sağ yarısına tez 2 dəfə toxun.",
"Tap the lightning bolt at the top right — the skills row opens.":"Yuxarıda sağdakı ildırıma toxun — bacarıqlar sırası açılacaq.",
"Use the stick to get behind the wall until the sniper marker turns grey.":"Stiklə snayper nişanı boz olana qədər divarın arxasına keç.",
"Tap \"⇆\" at the top right.":"Yuxarıda sağdakı «⇆»ə toxun.",
