"Tap \"◩ Strategy\" at the top right.":"Yuxarıda sağdakı «◩ Strategiya»ya toxun.",
"Tap \"▶ To battle\" at the top right (or \"Possess\" on the card).":"Yuxarıda sağdakı «▶ Döyüşə»yə toxun (və ya kartda «Boshqar»).",
"Drag one finger across the map.":"Bir barmaqla xəritə üzrə apar.",
"Pinch with two fingers — closer / farther.":"İki barmaqla sıx — yaxın / uzaq.",
"Tap the squad with the green marker.":"Yaşıl nişanlı otryada toxun.",
"Tap the yellow marker on the ground (double tap — run).":"Yerdəki sarı nişana toxun (2× toxun — qaçaraq).",
"Double tap a squad — all of that type on screen get selected.":"Otryada tez 2 dəfə toxun — ekrandakı eyni tipdən hamısı seçiləcək.",
"Hold a finger on empty ground until the yellow ring, then drag — a box appears.":"Barmağını boş yerdə sarı halqaya qədər saxla, sonra apar — çərçivə yaranacaq.",
"Hold a finger on the ground at the marker until the ring, then release — a radial menu opens.":"Barmağını nişanın yanında yerdə halqaya qədər saxla və burax — dairəvi menyu açılacaq.",
"Tap card \"2\" on the left (double tap — camera to the squad).":"Solda «2» kartına toxun (2× toxun — kamera dəstəyə).",
"Tap the minimap at the bottom left — the camera jumps there.":"Solda aşağıdakı mini xəritəyə toxun — kamera ora keçəcək.",
"Tap \"Builders\" on the right or the marked builder.":"Sağda «Muhandislər»ə və ya nişanlı muhandisə toxun.",
