"training complete":"təlim bitdi",
"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Yaxınlaşdırmaq üçün «Nişan»a toxun. Yenə toxun — geri.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Otryadın səni izləyir. ☰ → «Fasilə»ni aç → «Otryad mənimlə» lövhəsi — «Tək hərəkət edirəm» olacaq.",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Muhandis seçilib — aşağıdakı kartında «◆ Kristal çıxar»a toxun (və ya yaşıl kristallara toxun).",
"Training complete!":"Təlim bitdi!",
"steps":"addım",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Baza qurmağı, qoşun sifariş verməyi, komanda etməyi və döyüşə atılmağı bacarırsan. Növbəti — real matç: Kurator oyun gedişində kömək edəcək.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Hərəkət etməyi, uçmağı, atəş açmağı, gizlənməyi və otryada komanda verməyi bacarırsan. Növbəti — real matç.",
"Real battle":"Real döyüş",
"Again":"Yenə",
"done":"keçildi",
"you are on PC: keyboard and mouse":"səndə PC var: klaviatura və siçan",
"you are on a phone: touch screen":"səndə telefon var: sensor ekran",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Təhlükəsiz qum qutusu: düşmənlər hələ ki manekendir, səni heç kim vurmur. Addım yalnız hərəkəti özün etdikdə sayılır.",
"Show others (training for the other device)":"Başqalarını göstər (digər cihaz üçün təlimlər)",
"Old training (v7.1)":"Köhnə təlim (v7.1)",
"Back to the normal device mode":"Adi cihaz rejiminə qayıt",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Digər cihaz üçün təlim səhifəni onun rejimində yenidən yükləyəcək (PC — siçan və klaviatura, telefon — toxunuşlar; PC-də toxunuşları Chrome-da yoxlamaq rahatdır: F12 → telefon ikonu).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Təlim ×4: PC və telefon üçün ayrı-ayrı addım-addım \"Strategiya\" və \"Otuvchi\" dərsləri. Manekenlərlə təhlükəsiz sınaq meydançası, lazım olan düymənin işıqlandırılması, oxlar, animasiyalı düymələr, siçan və jestlər; addım yalnız real hərəkətə görə sayılır, \"addımı təkrarla\", yuxarıda irəliləyiş və sonda mükafat",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"\"Təlim\" menyusu cihazın üçün dərsləri özü göstərir; \"Başqalarını göstər\" — istənilən cihazda dördünü də; \"Köhnə təlim (v7.1)\" də yerindədir",
"New in v7.2":"v7.2-də yeniliklər",
"NEW IN v7.2":"v7.2-DƏ YENİLİKLƏR",
"No grenades left":"Qumbara qalmayıb",
"Rocket and grenade recharging · {0} s":"Raket və qumbara dolur · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Solda — hərəkət, sağda — baxış · düşmənə toxun — raket / qumbara · 2 toxunuş — refleks · 3 toxunuş — orbital zərbə",
"Less":"Az",
"More":"Çox",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Yaxında düşmən texnikası və ya tikilisi var — ona toxun: raket uçacaq.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Çoxlu düşmən var — sağda boş yerə tez 2 dəfə toxun: refleks vaxtı yavaşladacaq.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Nişanı düşmən qrupuna tuşla və 3 dəfə toxun — orbital zərbə.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Sol barmaq — hərəkət, sağ barmaq — baxış. Nişan düşmənin üstündə olanda özü atəş açır.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"Solda kənarda ⇑ — ranets: sıçramaq üçün toxun, uçmaq üçün saxla.",
"Old v7.2 layout":"Köhnə v7.2 yerləşməsi",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Barmağını ekranın sağ yarısında sürüşdür — altında baxış coystiki görünəcək.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Ekranın sol tərəfinə toxun və barmağını sürüşdür — altında coystik görünəcək. Yaşıl nişana çat.",
"Hold the \"Jet\" button at the left edge.":"Sol kənardakı \"Ranets\" düyməsini saxla.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Sağ coystiklə nişanı manekenə tuşla — nişan hədəfdə olanda jangchi özü atəş açır.",
"Tap the dummy on the screen — a rocket flies.":"Ekranda manekenə toxun — raket uçacaq.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Manekenə toxun — qumbara qövslə birbaşa hədəfə uçacaq.",
"Double tap an empty spot on the right quickly.":"Sağda boş yerə tez 2 dəfə toxun.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Zəif telefonlar üçün yüngül rejim: aşağı ayırdedici qabiliyyət, kölgəsiz və təhrifsiz, botlar və hissəciklər yarı qədər, 30 FPS limiti; FPS < 25 olsa, ayırdetməni özü azaldır. Telefonda standart olaraq aktivdir (Ayarlar → Qrafika → \"Yüngül rejim\"; və ya linkdə ?lite=1 / ?lite=0).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Telefon: yeni idarəetmə. Solda — hərəkət, sağda — baxış (hər iki coystik barmağın altında görünür). Yalnız sol barmaq — \"avto\"; sağ da işləyəndə jangchi yalnız nişan düşməndə olanda özü atır. Düşmənə toxun — raket və ya qumbara, 2 toxunuş — refleks, 3 toxunuş — artilleriya zərbəsi. Avtomatik doldurma. Ranets — sol kənarda düymə. Aşağı künclər sərbəstdir, mini xəritə küncdədir, məsləhətlər xaçla bağlanır, tapşırıq yığılır. Köhnə yerləşmə: Ayarlar → Telefon.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Məsləhətlər (pop-aplar və Kurator) — ayarlarda bir açar. Kimi oynadığın (jangchi və ya texnika növü) HUD-da \"Sən: …\" yazısıdır. Avtomat və pulemyotun optikası şəffafdır. \"Arsenal\" paneli sağa yapışıb, yığılır və söndürülür. \"Otryadsız təkbaşına\" (J) götürülüb. AI-strateg eyni sözü ardıcıl təkrarlamır. Tanklarda qüllənin gövdəyə nisbətən göstəricisi var. Strategiya təlimi başlayanda kursor artıq yoxa çıxmır.",
