" · AI drives vehicles, E next to one — man its gun":" · texnikanı AI sürür, maşının yanında E — topun arxasına keç",
"Possess squads (infantry)":"Dəstələri ələ keçir (piyada)",
"Possess vehicles and drones":"Texnikanı və dronları ələ keçir",
"On the gun: {0}. The AI drives, you shoot. {1} — get off":"Topun arxasındasan: {0}. AI sürür, sən atırsan. {1} — düş",
"The vehicle is destroyed — you jumped off":"Maşın məhv edildi — sən tullandın",
"{0} — get off the gun":"{0} — topdan düş",
"{0} — man the gun: {1}":"{0} — topun arxasına keç: {1}",
