"Voice of hints & curator":"Məsləhət və Kurator səsi",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Telefon: üç coystik rejimi. Yalnız sol — \"avto\" (güclü maqnit, zəif güllələr). Yalnız sağ — nişan özü işə düşür, maqnit güclüdür, atəş dəqiqdir. Hər ikisi — nişansız, maqnit və dəqiqlik azdır. Sağdakı 👁 düyməsi interfeysi gizlədir/qaytarır.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Telefon: strategiya sadələşdirilib — yalnız muhandis və binalar. Solda kartlar (muhandis, shtab, kazarma…): toxun — kamera ora uçur, aşağıda nə tikmək/istehsal etmək görünür. \"Döyüşə\" — yuxarı solda. Ordu özü döyüşür. Tam strategiya — Ayarlar → Telefon.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Boshqarish — iki qutu: \"Otryadlar\" və \"Texnika\" (telefonda texnika standart olaraq söndürülüdür — onu AI sürür). Texnika söndürülübsə, öz maşınının yanında E (telefonda — sağdakı düymə) — topun arxasına keç: maşın özü gedir, sən atırsan. Köhnə \"öz sinif sırası\" — \"İrəliləmiş\"dədir. Boshqarəndə yunit rasiyada cavab verir.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Ağıllı məsləhətlər: əsas məsləhətlər 2-ci başlatmadan sonra özü sönür, amma oyun heç istifadə etmədiyin funksiyanı xatırladır. Qutular: əsas / irəliləmiş / nadir, ayrıca — məsləhət və Kurator səsi.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Refleks öldürmələrdən dolur (seriya daha çox doldurur). Otryad yoldaşları geridə qalıb və ya ölüblərsə — AI-strateg sənə yenilərini göndərir (adi əlavə qüvvədən bahadır). v7.2gfx qrafikası və səsi birləşdirilib: qabarıq partlayışlar, tüstü, qalıqlar, şaxta və krater akustikası. Quraşdırma tarixi artıq həqiqidir.",
