"The sky is a portal: fly up and you come out on the opposite side of the meteor.":"Səma portaldır: yuxarı uçsan, meteoritin əks tərəfindən çıxacaqsan.",
"Follow the strategist's orders — XP for them is doubled and tripled.":"AI-strateqin əmrlərini yerinə yetir — onlara görə təcrübə iki və üç qat artır.",
"X — instantly switch to the squad or vehicle closest to the fight.":"X — döyüşə ən yaxın otryada və ya maşına dərhal keç.",
