"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Karyera və yadda saxlamalar dəyişməz qalır. Döyüşdə eyni menyu yuxarı sağdakı \"🛠 Menyu\" düyməsidir{0}.",
"New developer match":"Yeni tərtibatçı matçı",
"all unlocked, endless ore, instant build, arsenal":"hər şey açıq, sonsuz ruda, ani tikinti, arsenal",
"Trainings — all 4":"Təlimlər — hamısı 4",
"PC and phone (strategy and shooter)":"PC və telefon (strategiya və atıcı)",
"Cinema: split screen":"Kino: bölünmüş ekran",
"strategist bot left, shooter bot right":"solda bot-strateq, sağda bot-atıcı",
"Cinema: everything built":"Kino: hər şey tikilib",
"both bases built and upgraded — for footage":"hər iki baza tikilib və təkmilləşdirilib — çəkiliş üçün",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Kino rejimi — bölünmüş ekran: solda bot-strateq (baza və orduya yuxarıdan görünüş), sağda birinci şəxsdən bot-atıcı. Aşağıdakı düymələr (və S, P düymələri): \"Bölünmüş ekran\" və \"★ Hamısı tikilib\" — hər iki baza çəkiliş üçün tikilib və təkmilləşdirilib.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Nüvə və meteoritin içindən keçən tunellər artıq yoxdur — meteorit bütövdür, döyüş yalnız səthdə gedir.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Telefon: 👁 interfeysi gizlədir, amma ranetsi, ⇆-ı, çubuqları və tapşırıq markerini saxlayır. \"◎ Nişan\" (yalnız sağ barmaq) — nəzərəçarpacaq dərəcədə güclü və geniş maqnit; üç rejim üçün maqnit gücü — Ayarlar → İdarəetmə → \"Əlavə\". Maşının topunda düymə \"Düş\" adlanır.",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Təlim: telefonda yalnız telefon təlimləri, PC-də yalnız PC təlimləri. Hamısı 4-ü \"🛠 Tərtibatçı\" menyusundadır. Tərtibatçı rejimi və Arsenal indi bir menyudur (döyüşdə — yuxarı sağda \"🛠 Menyu\", PC-də F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"\"Dendy (8-bit)\" və \"16-bit\" qrafika stilləri: Ayarlar → Qrafika → \"Qrafika stili\" (təfərrüat — ⚙ düyməsi). Matçın ilk ~10 s-ində FPS 24-dən aşağı olarsa, Dendy özü qoşulur (20-dən də aşağıdırsa — daha iri piksel, 120 sətir); \"normala qaytar\" bildirişi normal qrafikanı həmişəlik bərpa edir. Menyuda öz seçimin həmişə üstündür.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D mühit modelləri (xarabalıqlar, qəzaya uğramış texnika, istehkamlar) — yalnız yaxşı qiymət alanlar, tələb olunduqda yüklənir. Söndürmək: Ayarlar → Qrafika → \"Yeni 3D mühit modelləri\".",
