"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Döyüşçülərlə tikinti: E (telefonda \"Daxil ol\") öz tikintinin yanında — döyüşçü özü tikir, yaxındakı yoldaşlar kömək edir. Mühəndislər məşğuldursa, strateq özü kömək istəyəcək — \"TİKİNTİ\" işarəsi.",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Strateq işarələri: strateq yaxınlığındakı düşmən toplaşmasına ⌖ qoyur — 8 s sonra oraya artilleriya vurur, yaxınlıqdakı öz \"Grad\" RZSA-ları isə salvo verir. Strategiya rejimindən öz artilleriya zərbən də \"Grad\"-ların dəstəyi ilə gedir.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Yük konteynerlərində və düşmüş peyklərdə silah gizlətmələri (📦 70 m-dən görünür): E — 90 s ağır pulemyot, yandırıcı patronlar və ya raketlər, üstəlik dolu qumbaralar. Sürünərək: Ctrl — yat / qalx (aşağı, sakit, daha dəqiq, amma yavaş).",
