"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"\"▶ Dərhal oyna\" — menyunun ilk düyməsi: portal səması altında qısa uçuş — və dərhal döyüş (keçmək üçün istənilən düymə və ya toxunuş).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Zərbələr hiss olunur: metal səs və qığılcımlar, nişangahda öldürmə işarəsi (başa — sarı), ×N seriya, partlayışlardan hamar silkələnmə, mühüm öldürmələrdə ağır çəkiliş. Silkələnməni, ağır çəkilişi və göstərişi Ayarlarda söndürmək olar.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Matçın yekunu: vaxt, məhvlər, ən yaxşı seriya, ★ MVP və ən yaxşı dəstə, matç kartı — \"⇪ Paylaş\", PNG və ya oyuna link.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Solda resursların altında \"indi nə etməli\" göstərişi: strategin əmri, ələ keçirmək üçün nöqtə, Galanın hücumu. ✕ və ya F7 — yığ.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Vərəqi bağlasan və ya yığsan, döyüş özü saxlanır — menyuda \"⟲ Davam et\".",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5 \"🕘 Oyun versiyası\" menyusunda qalıb — yenisi xoşuna gəlməsə. Anonim statistika (ad və poçt olmadan) indi göndərilir; söndürmək — Ayarlarda.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"\"Dərhal oyna\", zərbələrin hissi, paylaşma kartı ilə matç yekunu, \"nə etməli\" göstərişi, avtosaxlama",
"and older: v7.5, v7.4, milestones v1–v7.0":"və köhnələr: v7.5, v7.4, v1–v7.0 mərhələləri",
"New in v7.6":"v7.6-da yeniliklər",
"NEW IN v7.6":"v7.6-DA YENİLİKLƏR",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Matçdan əvvəl fraksiya seçimi: \"Konsorsium\" (güc zirehli ağır piyada, zireh və artilleriya) və ya \"Gala\" (sürət, dron dəstələri, təhrif edən ağır atışlar). AI digərini idarə edir. Seçim yadda saxlanır.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Hər fraksiyanın öz texnikası və unikalları var: Konsorsiumun — \"Karkidon\" tankı və \"Keramit lövhələr\", Galanın — \"Dron dəstəsi\" və \"Faza ranetsləri\". Balans bot matçları ilə yoxlanıb.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Partlayış kraterləri: artilleriya, raketlər və tank topları meteoritdə çuxurlar qazır — onlarda yeriyib və sürmək olar, içində gizlənmək mümkündür.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Piyada üçün 3-cü şəxs görünüşü (V, yadda qalır; telefonda — İdarəetmə) və topun hara dəyəcəyini göstərən işarəli hamar texnika kamerası.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6 \"🕘 Oyun versiyası\" menyusunda qalıb — yenisi xoşuna gəlməsə.",
