"Supply drop":"Təchizat qutusu",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Qüvvələrinizin yanına qutu atır: patron, qumbara, raket, silah hissələri, təmir dəsti.",
"\"Grad\" rocket strike":"\"Grad\" raket zərbəsi",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"3 saniyəyə geniş sahəyə 16 raket — artilleriyadan daha sürətli və daha geniş.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Dəstək: qutu, kəşfiyyat, \"Grad\", artilleriya (sonra 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"DİQQƏT: Gala \"Grad\"ı sizin rayona gəlir!",
"Warning! Rocket salvo on our position!":"Diqqət! Mövqeyimizə reaktiv salvo!",
"take the supply crate":"təchizat qutusunu götür",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Meteoritdə anomaliyalar (dalğa 1): \"Kuylovchi tomir\" — parlayan yaşıl kristal, uğuldayır və ritmik impulslarla yaxındakı hamını vurur; \"Girdab\" çəkir və çırpır, \"Şaqqıldaq\" çubuqlar arasında qövs yaradır, \"Köz qabı\" ayaq altında alovlanır, \"Turş duman\" və \"Linza\" (güllələri və görüntünü əyir) sürüşür.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomaliyalar əvvəlcədən hiss olunur (uğultu, parıltı, isti hava titrəyişi). Qumbara, raket və ya boltla boşalt (yanında E): yatacaq, bəzən artefakt qoyacaq — bir artı, bir mənfi ilə. Dəstə radio ilə xəbərdar edir, düşmənlər (və dostlar) bəzən içinə girir — yönəlt!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Qoʻmondonlik ochkolari ilə dəstək: döyüşdə 4 (telefonda 📡) — təchizat qutusu, kəşfiyyat, \"Grad\" raket zərbəsi, nişangahda artilleriya. Strateg xəritədə anomaliyaları yalnız skandan sonra görür.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Təchizat qutuları köhnə ekspedisiyaların xarabalarında, qərargahların yanında və tikilmiş binaların kənarında: patron, qumbara, raket, silah hissələri (əlavələri açır).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"v7.7 \"🕘 Oyun versiyası\" menyusunda qalıb. Anomaliyaları Ayarlarda söndürmək olar.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomaliyalar (\"Kuylovchi tomir\" və daha 5), bolt və qumbara ilə boşaltma, artefaktlar, QO ilə dəstək çağırışları, təchizat qutuları",
"and older: v7.7, v7.6, milestones v1–v7.0":"və köhnələr: v7.7, v7.6, v1–v7.0 mərhələləri",
"New in v7.8":"v7.8-də yeniliklər",
"NEW IN v7.8":"v7.8-DƏ YENİLİKLƏR",
"Close":"Bağla",
"Anomalies on the meteor":"Meteoritdə anomaliyalar",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"Küncdəki ☰ pauza menyusunu açır: Davam et, Yenidən başla, Təlim, Qrafika, Ayarlar, Əsas menyu (təsdiqlə). Telefon: yuxarı sağda ☰ (döyüş hərəkətləri — \"⚡ Hərəkətlər\" lövhəsi); PC: yuxarı sağda \"☰ Menyu\" düyməsi və ya Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Qrafika susmaya görə həmişə adidir — Dendy yalnız seçsən: \"Qrafika: Adi / Dendy (8-bit) / 16-bit\" açarı birbaşa əsas menyuda və pauzadadır. Oyun çox donarsa, \"Dendy-ni aç\" düyməli məsləhət çıxır.",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Telefon və planşet: sağdakı \"✋\" hərəkət düyməsi yalnız yaxında nəsə etmək mümkün olanda çıxır — \"Götür\" (gizlətmə, qutu), \"Min\" (texnika, qüllə, top), \"İnşa et\", \"Düş\", anomaliya yanında \"Bolt\". Vurğulanmış əşyaya sadəcə toxuna da bilərsən.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Telefon, strategiya: barmağı ~0,3 s saxla (telefon titrəyəcək, sarı halqa çıxacaq) və sürüşdür — seçim çərçivəsi; adi sürüşdürmə kameranı hərəkət etdirir. Sağda \"Çərçivə\" düyməsi də var; təlimdə \"Çərçivə\" addımı dəstəyə toxunmağı da qəbul edir.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Telefon: kiçik düymələrə basmaq asanlaşdı, 📡 dəstək siyahısı böyüdü, strategiya panelləri pauza və nəticə ekranlarının üstünə çıxmır. v7.8 \"🕘 Oyun versiyası\" menyusunda qalıb.",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"Telefonda və PC-də ☰ menyu, avto-Dendy yoxdur, toxunuşda \"✋\" düyməsi, telefonda çərçivə ilə seçim",
"16-bit":"16-bit",
