"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Qəhrəman (hər tərəfə 1): düşmən zonalarına özü teleport olur və robotları doğrayır; əllə oynamaq üçün Boshqarish rejimini seç.",
