"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AVTO: özü düşmən zonalarına tullanır və doğrayır. Cızıq / WASD — 1.5 s pauza",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Əllə: düşmənə toxun — cəld hərəkət və zərbə, sürüşdür — zərbə, 🛡 — blok",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Əllə idarə: sol düymə — katana, sağ düymə — blok, Shift — cəld hərəkət, Q — şurikenlər, G — teleport",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ninja: düşmənə toxun — şığıyıb vur, sağda sürüşdür — zərbə, ● — vur, 🛡 — blok (vaxtında = dəf etmə), ⇑ — sıçrayış, ✦ — şurikenlər, ◎ — teleport, AVTO — özü",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ninja: sol düymə — katana (basılı saxla — ağır zərbə), sağ düymə — blok (vaxtında = dəf etmə), Shift/Z — sıçrayış, Q — şurikenlər, G — nişangaha teleport, havada tullanış — ikiqat tullanış / divarda qaçış, {0} — AVTO",
