"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Portal Meteor Radiosu: EDMITRY-nin 100+ treki birbaşa oyunda — 📻 düyməsi (PC: 5 düyməsi, [ ] — trek). Musiqi tələb olunduqca yüklənir və oyunu ağırlaşdırmır; səs və avtomatik başlama Ayarlarda, həmçinin \"Spotify-da dinlə\" linki.",
