"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-ninja: katanalı kiborq. Kazarmada \"Kölgə protokolu\" tədqiqatı ilə açılır (Mexa zavodu lazımdır). Özü düşmən zonalarına teleport olur, düşmənləri doğrayır (qan yoxdur — qığılcımlar), sıçrayışlar, şurikenlər, düşmən ninjası ilə duellər. Onu Boshqarish — AVTO rejim və ya əl ilə idarə (telefonda öz düymələri var).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Portal Meteor Radiosu: EDMITRY-nin 103 treki birbaşa oyunda. 5 düyməsi (dəyişdirilə bilər), telefonda — ☰ → Ayarlar → Səs. Səs və \"döyüşdə özü başlasın\" ayarlardadır; musiqi partlayışlarda və rasiya səsinin altında aşağı düşür.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Yeni dillər: özbək və tacik — tam; çin, ispan, portuqal — qismən. Menyuda \"Yeni oyun\"un yanında yeni dil seçimi.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Telefon: \"işarələri gizlət\" 👁 qalan düymələri sağ kənarda səliqəli sütunda toplayır; portret rejimi artıq üst-üstə düşmür; iPhone — oyun Safari jestləri ilə toqquşmur, \"Paylaş → Ana ekrana əlavə et\" isə onu tam ekranda açır.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"v7.8.1-dən: küncdə ☰ menyusu (fasilə, yenidən, təlim, qrafika), avto-Dendy yoxdur, telefonda ✋ əməliyyat düyməsi. v7.8.1 və v7.8 \"🕘 Oyun versiyası\" menyusunda qalır.",
