"Napalm":"Napalm",
"A 12 m fire zone burns for 9 seconds: damage over time, suppression, smoke. After 2.5 s. Ignites methane.":"12 m-lik od zonası 9 saniyə yanır: zamanla zərər, sıxışdırma, tüstü. 2.5 s sonra. Metanı alışdırır.",
