"Support: crate, recon, \"Grad\", artillery, carpet bombing, napalm (then 1–6)":"Dəstək: yeşik, kəşfiyyat, \"Grad\", artilleriya zərbəsi, xalça bombardmanı, napalm (sonra 1–6)",
"☄ Meteor shower in 10 s — take cover: the rock hangar, under a ridge!":"☄ 10 s-dən sonra meteorit yağışı — sığınacağa: qayalardakı anqar, silsilənin altı!",
