"Consortium. 7 m wall section: stops bullets, shells and vehicles. Chain them (Shift+click).":"Konsorsium. 7 m-lik divar hissəsi: güllələri, mərmiləri və texnikanı saxlayır. Zəncirlə qur (Shift+klik).",
"Repair post":"Taʼmirlash posti",
"Consortium. Repairs vehicles, buildings and infantry within 26 m.":"Konsorsium. 26 m radiusda texnikanı, binaları və piyadaları təmir edir.",
