"⚠ Rumbling underground: the Swarm is digging a tunnel! Breakthrough in ~10 s — be ready":"⚠ Yeraltında gurultu: Gala tunel qazır! ~10 s-dən sonra çıxacaq — hazır ol",
"Warning! Digging heard. The enemy is tunnelling":"Diqqət! Qazıntı səsi eşidirik. Düşmən tunel qazır",
"Needs a Tunnel burrow — builders make it":"Tunel yuvası lazımdır — onu muhandislər tikir",
