"LMB — exit point (up to {0} m from the burrow), RMB — cancel":"Sol düymə — çıxış nöqtəsi (yuvadan {0} m-ə qədər), sağ düymə — ləğv et",
"Dig the exit first":"Əvvəlcə çıxış qaz",
