"Digging: {0} s. The enemy will hear it 10 s before breakthrough":"Qazırıq: {0} s. Düşmən çıxışdan 10 s əvvəl gurultu eşidəcək",
"Exit · {0} m · {1} s":"Çıxış · {0} m · {1} s",
"Dig the exit":"Çıxış qaz",
"Swarm. Pick a point up to 220 m away — the exit breaks through in 24 s. 10 s before, the enemy hears rumbling and sees dust.":"Gala. 220 m-ə qədər nöqtə seç — çıxış 24 s-dən sonra açılır. 10 s əvvəl düşmən gurultu eşidir və toz görür.",
