"Swarm. Boss: 12500 hull, distortion beam, stomp. Steps over barriers. Weak spot — the core underneath. One per army.":"Gala. Boss: 12500 möhkəmlik, təhrif şüası, tapdalama. Baryerlərin üstündən keçir. Zəif nöqtə — qarın altındakı nüvə. Orduya bir dənə.",
