"Strip: ⟳ to rotate, or drag from the target along the run":"Zolaq: ⟳ — çevir, yaxud barmağınla hədəfdən hücum istiqamətinə doğru sürüşdür",
"Strip: mouse wheel or R to rotate, or drag from the target along the run":"Zolaq: siçan çarxı və ya R — çevir, yaxud siçanla hədəfdən hücum istiqamətinə doğru sürüşdür",
