"Swarm. Squads within 70 m of the burrow (and selected ones), plus selected light/medium vehicles (Jackal, Hammer, Grad), go through the tunnel. Or: select and RMB/tap the burrow.":"Gala. Yuvadan 70 m-dək məsafədəki otryadlar (və seçilmişlər) və seçilmiş yüngül/orta texnika (\"Chiyaboʻri\", \"Bolgʻa\", \"Grad\") Tunnel ini vasitəsilə keçib o biri ucdan çıxır. Yaxud: seç və yuvaya oʻng tugma/toxun.",
"Air strikes":"Hava zərbələri",
"Carpet bombing and napalm: aiming, rotating the strip, enemy warning, calling from battle":"Xalça bombardmanı və napalm: nişan, zolağın çevrilməsi, düşmən xəbərdarlığı, döyüşdən çağırış",
"Terrain and lakes":"Relyef və göllər",
"Lava burns, ice slides, methane explodes from fire, the rock hangar is cover":"Lava yandırır, buz sürüşdürür, metan oddan partlayır, qayadakı anqar sığınacaqdır",
"Swarm: tunnels":"Gala: tunellər",
"You play the Swarm: tunnel burrow, exit up to 220 m, dust warning, squads and vehicles through":"Gala ilə oynayırsan: Tunnel ini, 220 m-dək çıxış, toz xəbərdarlığı, otryadlar və texnika tunellə",
"Consortium: fortifications":"Konsorsium: istehkamlar",
"You play the Consortium: barrier chains, repair post, field repair by builders":"Konsorsium ilə oynayırsan: baryer zənciri, Taʼmirlash posti, muhandislərin səhra təmiri",
"Bosses":"Bosslar",
"\"Bastion\" and \"Reaper\": from 12:00 (skipped here), plant, assembly, orders, weak spots, possession":"\"Bastion\" və \"Oʻroqchi\": 12:00-dan (dərsdə sürüşdürülüb), zavod, yığım, əmr, zəif nöqtələr, ələ keçirmə",
"ENEMY STRIKE":"DÜŞMƏN ZƏRBƏSİ",
