"Living world: requests, hero quests, breakthrough ops":"Canlı dünya: xahişlər, qəhrəman tapşırıqları, yarılma əməliyyatları",
"Living world":"Canlı dünya",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Öz adamların kömək istəyir və mükafatlandırır, qəhrəmanlar tapşırıq verir, durğun cəbhəni əməliyyat yarır",
"A request":"Öz adamların xahişi",
"Breakthrough":"Yarılma",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Öz adamların bəzən kömək istəyir: radioda səs, «XAHİŞ» kartı və ✋ işarəsi. Otryadı sıxışdırıblar — yanındakı düşmənləri məhv et. Mükafat: bazadan kapsulla jangchi, bagi yükündən silah, atıcı yeri və ya orbitdən örtük. İstəmirsən — ✕ və ya sadəcə fikir vermə.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Veteran kəşfiyyatçı «Boyqush» tapşırıq təklif edir. Y — qəbul et (N — rədd et). ★ işarəsinə get, mühafizəni təmizlə və pilotun yanında 3 s dur — o, otryadına qoşulacaq.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Cəbhə dayanıb — shtab yarılma təklif edir. Y — qəbul et. Ötürücünü yaxında düşmən olmadan 8 s saxla: düşmən xəritəsi 60 s görünür. Generator — düşmən turelləri 2 dəq susur. Strateg rejimində — «Otryadga ber». Düşmən də bunu bacarır: ⚠-ə fikir ver.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Öz adamların kömək istəyir: «XAHİŞ» kartı və ✋ işarəsi. Sıxışdırılmış otryadın yanındakı düşmənləri məhv et — mükafat alacaqsan. ✕ — ötür.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"«Boyqush» qəhrəmanı tapşırıq təklif edir — «Qəbul et»ə toxun. ★-a get, mühafizəni təmizlə, pilotun yanında dur.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Cəbhə dayanıb — «Qəbul et»ə toxun və ötürücünü 8 s saxla: düşmən xəritəsi bir dəqiqəliyə açılacaq.",
