"Base":"Baza",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Bazanın ürəyi: otryadlar, muhandislər, kapsulalar, tədqiqatlar. Shtabı itirsən — uduzursan.",
"Produces: ":"İstehsal edir: ",
"Launch pad":"Buraxılış meydançası",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Shtabın yanındakı silos: kapsulalar, təchizat qutuları və bombardmançılar buradan səma portalı ilə hədəfə uçur. Üzərində tikinti aparmaq olmaz.",
"Economy":"İqtisadiyyat",
"Key building":"Əsas tikili",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Zəif nöqtə — arxa (mühərrik): zərər ×{0}. Top, 2 pulemyot turəli, raket kasseti; çox yavaş dönür — yandan keçin.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Zəif nöqtə — qarnın altındakı parlayan nüvə: aşağıdan zərər ×{0}. Təhrif şüası və sahəvi tapdalama; baryerlərin üstündən keçir — məsafə saxlayın, bir yerə yığılmayın.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Qarşı: aviabombalar və artilleriya (×{0}), raketlər (×{1}), xalça bombardmanı; güllələr demək olar ki, təsirsizdir (×{2}).",
"Faction":"Fraksiya",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Sürətli maşınlar, dron sürüləri, tunellər və regenerasiya. Piyadalar yüngül, amma sürətlidir; toplar və reyk silahları daha güclü vurur.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Güc zirehli ağır piyadalar, beton baryerlər, təmir və artilleriya. Daha yavaş, amma daha möhkəmdir.",
