"Tell (radio): ":"Əlamət (radio): ",
"Discharge: an explosion or a thrown bolt (E / \"Bolt\") — it sleeps 20–35 s, sometimes leaves an artifact.":"Boşaltma: partlayış və ya atılmış bolt (E / «Bolt») — 20–35 s yatır, bəzən artefakt qoyur.",
"Artifacts":"Artefaktlar",
"Reward":"Mükafat",
"Sometimes left after an anomaly is discharged. Always a plus and a minus, last 3 minutes.":"Anomaliya boşaldıqdan sonra bəzən qalır. Həmişə bir artı və bir mənfi olur, 3 dəqiqə təsir edir.",
"Verdans":"Verdanlar",
"Plant race":"Bitki irqi",
"Live in the Green anomalous zone, drawn to crystal veins. Neutral until touched or approached; dangerous to both sides. Fire and napalm ×1.6.":"«Yaşıl anomal zonada» yaşayır, kristal damarlara can atır. Toxunmayana və yaxınlaşmayana qədər neytraldır; hər iki tərəf üçün təhlükəlidir. Od və napalm ×1.6.",
"Biome":"Biom",
"Weather":"Hava",
"A humming green crystal that pulses around itself — it flashes before each pulse.":"Uğuldayan yaşıl kristal ətrafa ritmik impulslar yayır — impulsdan əvvəl alışıb-sönür.",
"Pulls you to the centre and slams you down. Look for rocks floating above it.":"Mərkəzə çəkir və yerə çırpır. Qıfın üstündə süzən daşlardan görünür.",
"Electric arcs between rods hit everyone inside, vehicles too.":"Çubuqlar arasındakı elektrik qövsləri içəridəki hamını vurur, texnikanı da.",
"Step on it and a pillar of fire bursts out. The air shimmers above it.":"Üstünə çıxsan — od sütunu. Üstündə isti hava titrəyir.",
"A drifting green cloud: damage over time while inside.":"Sürüşən yaşıl bulud: içində durduqca zamanla zərər verir.",
"A drifting space distortion: bends bullets and warps the screen.":"Sürüşən fəza təhrifi: güllələri əyir, ekran «axır».",
"Dust falls upwards: a unit is pulled into the sky portal and thrown out at the antipode ~5 s later (exit visible to both sides).":"Toz «yuxarı düşür»: vahidi səma portalına aparır və ~5 s sonra antipodda atır (çıxış hər iki tərəfə görünür).",
"A 10×10 m square of big \"pixels\": jerky movement, +50% spread, AI loses targets.":"İri «piksellərdən» 10×10 m kvadrat: hərəkət sıçrayışlıdır, səpələnmə +50 %, AI hədəfləri itirir.",
"Frost on the ground, 2 s of hissing — then a steam column: freeze (−60% speed, +40% blast damage, 8 s). Snow.":"Yerdə şaxta, 2 s fısıltı — sonra buxar sütunu: donma (−60 % sürət, partlayışdan +40 % zərər, 8 s). Qar.",
"A 6×30 m strip of haze pushes units, jetpacks and even projectiles; direction changes every 2 minutes. Autumn.":"6×30 m-lik sərab zolağı vahidləri, ranetləri, hətta mərmiləri itələyir; istiqamət 2 dəqiqədən bir dəyişir. Payız.",
"Grey static: no radio or support inside, robot vision ×0.4, shots are quiet.":"Boz statika: içəridə radio və dəstək yoxdur, robotların görüşü ×0.4, atəş səssizdir.",
"A meadow of steel dandelions: fluff sticks and corrodes armour −2/s, jumps to neighbours on contact.":"Polad zəncirotu çəmənliyi: Poʻlat momiq yapışıb zirehi −2/s yeyir, toxunduqda qonşulara keçir.",
"A rootstock with vines: barely moves, lashes everyone nearby (damage and knockback).":"Sarmaşıqlı kök gövdəsi: demək olar ki, yerindən tərpənmir, yanındakı hamını sarmaşıqla qamçılayır (zərər və geri itələmə).",
"Hit it from range — beyond its aggro radius it is harmless.":"Uzaqdan vurun — aqressiya radiusundan kənarda təhlükəsizdir.",
"A mushroom with a glowing cap: touch or approach it and it bursts into spores (damage and suppression, 6 s).":"Parlayan papaqlı göbələk: toxunsan və ya yaxınlaşsan — spor buludu (zərər və boğma, 6 s).",
"Shoot from afar or walk around.":"Uzaqdan atəş açın və ya yan keçin.",
"Armoured and slow, bullets barely work; anger it and it rams.":"Zirehli və yavaşdır, güllələr demək olar ki, tutmur; qıcıqlandırsan — şığıyır.",
"Rockets, grenades, fire.":"Raketlər, qumbaralar, od.",
"A three-legged hunter: get close and it chases you and claws, gives up after 20 s.":"Üç ayaqlı ovçu: yaxına getsən — qovur və caynaqla vurur, 20 s sonra əl çəkir.",
"Keep your distance or escape by jetpack.":"Məsafə saxlayın və ya ranetlə qaçın.",
"A rootstock on root legs: burrows (a dust mound moves underground, invulnerable), surfaces under its target and tosses it.":"Kök ayaqlı kök gövdəsi: yerə girir (torpaq təpəciyi yeraltı gedir, toxunulmazdır), hədəfin altından çıxıb onu havaya atır.",
"Watch the mound and back off; hit it while it is above ground.":"Təpəciyə baxın və geri çəkilin; üstdə olarkən vurun.",
"A cloud of glowing worms: chases you and nibbles; bullets barely work.":"Parlayan qurdcuqlar buludu: qovub azca dişləyir, güllələr demək olar ki, təsirsizdir.",
"An explosion scatters it for 6 s — a grenade beats the MG.":"Partlayış sürünü 6 s dağıdır — qumbara pulemyotdan yaxşıdır.",
"Dust and basalt, caps around the HQs, lava. Standard combat rules.":"Toz və bazalt, shtabların ətrafında papaqlar, lava. Adi döyüş qaydaları.",
"Emerald grass, spores, crystals: the grass hides infantry beyond 40 m until it fires. Verdans live here.":"Zümrüd ot, sporlar, kristallar: ot piyadanı gizlədir — 40 m-dən uzaqda atəş açana qədər görünmür. Verdanlar burada yaşayır.",
"Autumn leaves: footsteps are louder — the enemy hears runners at 32 m. Draughts and Steel fluff appear here.":"Payız yarpaqları: addımlar daha səsli olur — düşmən qaçanları 32 m-dən eşidir. Burada küləklər və Poʻlat momiq olur.",
"Snow: infantry −15% speed, vision ×0.7, an ice lake nearby; blizzards and coolant geysers.":"Qar: piyada −15 % sürət, görüş ×0.7, yaxında buz göl; boran və soyuducu geyzerlər.",
"Visibility ×0.65, footsteps are silent.":"Görünmə ×0.65, addım səsləri eşidilmir.",
"Visibility 25 m: the AI cannot target beyond it.":"Görünmə 25 m: AI bundan uzaq hədəfi tutmur.",
"From big explosions, wrecks and napalm (30 s): targets in smoke beyond 10 m are hidden.":"Böyük partlayışlardan, vurulmuş texnikadan və napalmdan (30 s): tüstüdəki hədəf 10 m-dən uzaqda görünmür.",
"White cap only: visibility ×0.5, a white veil.":"Yalnız «Ağ papaqda»: görünmə ×0.5, ağ pərdə.",
"Dust storm and meteor shower":"Toz fırtınası və meteorit yağışı",
"Cut vision hard; falling rocks hit everyone — take cover.":"Görüşü kəskin azaldır; göydən düşən daşlar hamını vurur — sığınacağa çəkilin.",
