"Ladder":"Nərdivan",
"Strategist → Commander → Shooter: one mode button (PC Tab/P, phone — top button, gamepad — View; hold to pick).":"Strateg → Komandir → Otuvchi: bir rejim düyməsi (PC — Tab/P, telefon — yuxarıdakı düymə, gamepad — View; basılı saxla — üçdən seç).",
"Pause: Esc / ☰ / Menu. Help: F1 in battle, full key list \"/\". Clean screen F9.":"Pauza: Esc / ☰ / Menu. Kömək: döyüşdə F1, düymələrin tam siyahısı — «/». Təmiz ekran — F9.",
"Mode":"Rejim",
"Top view: building, production, group orders, CP support. LMB select, RMB order; on phone — taps and the build panel.":"Yuxarıdan görünüş: tikinti, istehsal, qruplara əmrlər, QO ilə dəstək. Chap tugma — tanlash, oʻng tugma — buyruq; telefonda — toxunuşlar və tikinti paneli.",
"Buildings: Z X C V B N K · v8.0 groups on the right · ":"Tikililər: Z X C V B N K · v8.0 qrupları sağda · ",
"Tilted camera over your squad: click to move, on an enemy to attack, 1–4 abilities, Tab next squad, double-click a trooper to dive into the shooter.":"Otryadın üstündə əyik kamera: klik — get, düşmənə klik — hücum et, 1–4 — qabiliyyətlər, Tab — növbəti otryad, əsgərə ikiqat klik — Otuvchi rejiminə dal.",
"Camera: Q/E, wheel, WASD, Space — back to squad.":"Kamera: Q/E, təkər, WASD, Space — otryada qayıt.",
"First-person combat as any trooper or vehicle. Jetpack, slide, grenade, rocket, reflex, artillery, rifle-butt melee.":"İstənilən əsgər və ya texnikanın gözü ilə birinci şəxsdən döyüş. Jetpack, sürüşmə, qumbara, raket, refleks, artilleriya, qundaq zərbəsi.",
"Phone: left joystick to move, right half to look, buttons on the right.":"Telefon: sol cövstik — hərəkət, sağ yarım — baxış, düymələr sağda.",
