"Three modes on one button: Shooter (you fight yourself), the new Commander (lead one squad, 4 abilities per unit type) and Strategist. On the phone — a simple interface: fewer buttons, modes unlock during the battle.":"Bir düymə ilə üç rejim: Otuvchi (özün döyüşdəsən), yeni Komandir (bir otryadı aparırsan, hər növün 4 qabiliyyəti var) və Strateg. Telefonda — sadə interfeys: daha az düymə, rejimlər döyüş gedişində açılır.",
