"Factions play differently: the Swarm digs tunnels and regenerates, the Consortium builds barriers and repairs. From minute 12 — the Bastion and Reaper bosses; you can possess your own.":"Fraksiyalar fərqli oynayır: Gala tunellər qazır və sağalır, Konsorsium baryerlər qurur və texnikanı təmir edir. 12-ci dəqiqədən — \"Bastion\" və \"Oʻroqchi\" bossları; öz bossuna keçə bilərsən.",
"Living world: your troopers ask for help over the radio (with a reward), heroes give quests, a stalled front gets a \"Breakthrough\" operation. Capsules, crates and strikes launch from the base through the sky portal.":"Canlı dünya: öz jangchilərin radio ilə kömək istəyir (mükafatla), qəhrəmanlar tapşırıq verir, cəbhə durğunlaşanda \"Dönüş nöqtəsi\" əməliyyatı başlayır. Kapsullar, qutular və zərbələr bazadan səma portalı vasitəsilə start götürür.",
"Faster (a frame up to 2x cheaper), gamepad in every mode, tablet layout, an encyclopedia of everything in the game, feedback mode — a note with a screenshot on one key.":"Daha sürətli (kadr 2 dəfəyə qədər ucuz), bütün rejimlərdə geympad, planşet düzülüşü, oyundakı hər şeyin ensiklopediyası, rəy rejimi — ekran görüntülü qeyd bir düymə ilə.",
"All new texts are translated into Uzbek, Tajik, Chinese, Spanish, Portuguese and Hebrew. The v7.9 ninja and radio stay; v7.9 is in the \"🕘 Game version\" menu.":"Bütün yeni mətnlər özbək, tacik, çin, ispan, portuqal və ivrit dillərinə tərcümə olunub. v7.9-un robo-ninja və radiosu yerindədir; v7.9 \"🕘 Oyun versiyası\" menyusundadır.",
